(9, 1, '2026-09-05 14:38:23', '2026-09-05 14:38:23', '<!-- wp:cover {\"url\":\"http://localhost/portfolio/wp-content/uploads/2026/09/Adobe-Express-file-1024x678.jpg\",\"id\":22,\"dimRatio\":40,\"overlayColor\":\"ast-global-color-3\",\"isUserOverlayColor\":true,\"minHeight\":600,\"sizeSlug\":\"large\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--30);min-height:600px\"><img class=\"wp-block-cover__image-background wp-image-22 size-large\" alt=\"\" src=\"http://localhost/portfolio/wp-content/uploads/2026/09/Adobe-Express-file-1024x678.jpg\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-ast-global-color-3-background-color has-background-dim-40 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"align\":\"wide\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|ast-global-color-4\"}}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"ast-global-color-4\",\"fontSize\":\"x-large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center alignwide has-ast-global-color-4-color has-text-color has-link-color has-x-large-font-size\">Discover Your Next Adventure</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|ast-global-color-7\"}}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"ast-global-color-7\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-ast-global-color-7-color has-text-color has-link-color has-medium-font-size\">Explore breathtaking destinations, unforgettable experiences, and journeys made for you</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Destinations</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Popular Destinations</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\",\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"color\":{\"background\":\"#ededed\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"width\":\"1px\",\"radius\":{\"topLeft\":\"5px\",\"topRight\":\"5px\",\"bottomLeft\":\"5px\",\"bottomRight\":\"5px\"}}},\"borderColor\":\"cyan-bluish-gray\"} -->\n<div class=\"wp-block-column has-border-color has-cyan-bluish-gray-border-color has-background\" style=\"border-width:1px;border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px;background-color:#ededed;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"id\":27,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/istockphoto-2135023427-612x612-1.webp\" alt=\"\" class=\"wp-image-27\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Bali</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>A tropical paradise filled with beautiful beaches, vibrant culture, and unforgettable experiences.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Bali</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"color\":{\"background\":\"#ededed\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"width\":\"1px\",\"radius\":{\"topLeft\":\"5px\",\"topRight\":\"5px\",\"bottomLeft\":\"5px\",\"bottomRight\":\"5px\"}}},\"borderColor\":\"cyan-bluish-gray\"} -->\n<div class=\"wp-block-column has-border-color has-cyan-bluish-gray-border-color has-background\" style=\"border-width:1px;border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px;background-color:#ededed;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"id\":28,\"width\":\"355px\",\"height\":\"235px\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/leonard-cotte-R5scocnOOdM-unsplash-1-scaled.jpg\" alt=\"\" class=\"wp-image-28\" style=\"object-fit:cover;width:355px;height:235px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Paris</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Experience charming streets, world-famous cuisine, and unforgettable moments.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Paris</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"color\":{\"background\":\"#ededed\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"width\":\"1px\",\"radius\":{\"topLeft\":\"5px\",\"topRight\":\"5px\",\"bottomLeft\":\"5px\",\"bottomRight\":\"5px\"}}},\"borderColor\":\"cyan-bluish-gray\"} -->\n<div class=\"wp-block-column has-border-color has-cyan-bluish-gray-border-color has-background\" style=\"border-width:1px;border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px;background-color:#ededed;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"id\":29,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/darcey-beau-q8D7WZc40eA-unsplash-1-scaled.jpg\" alt=\"\" class=\"wp-image-29\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading ha