:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"color\":{\"gradient\":\"linear-gradient(135deg,rgb(238,238,238) 57%,rgb(169,184,195) 83%)\"},\"border\":{\"radius\":{\"topLeft\":\"5px\",\"topRight\":\"5px\",\"bottomLeft\":\"5px\",\"bottomRight\":\"5px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-column has-background\" style=\"border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px;background:linear-gradient(135deg,rgb(238,238,238) 57%,rgb(169,184,195) 83%);padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"id\":39,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/mike-swigunski-k9Zeq6EH_bk-unsplash-2-1024x576.jpg\" alt=\"\" class=\"wp-image-39\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Maldives</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Escape to crystal-clear waters, white sandy beaches, and peaceful island resorts.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Maldives</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"color\":{\"gradient\":\"linear-gradient(135deg,rgb(238,238,238) 56%,rgb(169,184,195) 81%)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"5px\",\"topRight\":\"5px\",\"bottomLeft\":\"5px\",\"bottomRight\":\"5px\"}}}} -->\n<div class=\"wp-block-column has-background\" style=\"border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px;background:linear-gradient(135deg,rgb(238,238,238) 56%,rgb(169,184,195) 81%);padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"id\":40,\"width\":\"350px\",\"height\":\"198px\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/ricardo-gomez-angel-58uZCE8zrdk-unsplash-1-1024x683.jpg\" alt=\"\" class=\"wp-image-40\" style=\"object-fit:cover;width:350px;height:198px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Switzerland</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Discover breathtaking alpine landscapes, charming villages, crystal-clear lakes, and unforgettable mountain adventures.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Switzerland</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"color\":{\"gradient\":\"linear-gradient(135deg,rgb(238,238,238) 51%,rgb(169,184,195) 82%)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"5px\",\"topRight\":\"5px\",\"bottomLeft\":\"5px\",\"bottomRight\":\"5px\"}}}} -->\n<div class=\"wp-block-column has-background\" style=\"border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px;background:linear-gradient(135deg,rgb(238,238,238) 51%,rgb(169,184,195) 82%);padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"id\":41,\"width\":\"350px\",\"height\":\"198px\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/jezael-melgoza-NiyRORf8d8I-unsplash-1-1024x677.jpg\" alt=\"\" class=\"wp-image-41\" style=\"object-fit:cover;width:350px;height:198px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Tokyo, Japan</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Experience a fascinating blend of modern technology, ancient traditions, incredible food, and vibrant city life.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Tokyo</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Destinations', '', 'publish', 'closed', 'closed', '', 'destinations', '', '', '2026-09-05 19:26:26', '2026-09-05 19:26:26', '', 0, 'http://localhost/portfolio/?page_id=11', 0, 'page', '', 0),
