(15, 1, '2026-09-05 14:39:43', '2026-09-05 14:39:43', '<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Choose Your Perfect Travel Package</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Discover thoughtfully designed travel packages with unforgettable experiences, comfortable stays, and adventures for every kind of traveler.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"color\":{\"gradient\":\"linear-gradient(135deg,rgb(255,206,236) 51%,rgb(152,150,240) 73%)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"10px\",\"topRight\":\"10px\",\"bottomLeft\":\"10px\",\"bottomRight\":\"10px\"}}}} -->\n<div class=\"wp-block-column has-background\" style=\"border-top-left-radius:10px;border-top-right-radius:10px;border-bottom-left-radius:10px;border-bottom-right-radius:10px;background:linear-gradient(135deg,rgb(255,206,236) 51%,rgb(152,150,240) 73%);padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"id\":27,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"5px\",\"topRight\":\"5px\",\"bottomLeft\":\"5px\",\"bottomRight\":\"5px\"}}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/istockphoto-2135023427-612x612-1.webp\" alt=\"\" class=\"wp-image-27\" style=\"border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px\"/></figure>\n<!-- /wp:image -->\n