(50, 1, '2026-09-05 18:26:49', '2026-09-05 18:26:49', '<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">About Wanderly</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Wanderly is your companion for discovering inspiring destinations, planning unforgettable journeys, and creating memories that last a lifetime.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">We help travelers discover amazing destinations, choose the right experiences, and plan journeys with confidence. From relaxing beach escapes to exciting city adventures, Wanderly brings travel inspiration together in one place.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Why Travelers Choose Us</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Personalized Journeys</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Travel ideas designed around your interests and style.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Trusted Inspiration</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Helpful guides and carefully selected destinations to inspire your next trip.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Unforgettable Memories</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Discover experiences that turn every journey into a story worth remembering.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'About', '', 'inherit', 'closed', 'closed', '', '17-revision-v1', '', '', '2026-09-05 18:26:49', '2026-09-05 18:26:49', '', 17, 'http://localhost/portfolio/?p=50', 0, 'revision', '', 0),
