(60, 1, '2026-09-05 19:10:08', '2026-09-05 19:10:08', '<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Get in Touch</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Have a question, need help planning your trip, or simply want to say hello? We’d love to hear from you. Get in touch with the Wanderly team and let’s start your next journey together.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Email Us</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><a href=\"mailto:hello@wanderly.com\">hello@wanderly.com</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Call Us</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">+91 98765 43210</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Visit Us</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Bhubaneswar, Odisha, India</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Send Us a Message</h2>\n<!-- /wp:heading -->\n\n<!-- wp:wpforms/form-selector {\"clientId\":\"a316deb5-253d-4182-84f0-2a860c3e8652\",\"formId\":\"54\",\"copyPasteJsonValue\":\"{\\u0022displayTitle\\u0022:false,\\u0022displayDesc\\u0022:false,\\u0022theme\\u0022:\\u0022\\u0022,\\u0022themeName\\u0022:\\u0022\\u0022,\\u0022fieldSize\\u0022:\\u0022medium\\u0022,\\u0022backgroundImage\\u0022:\\u0022none\\u0022,\\u0022backgroundPosition\\u0022:\\u0022center center\\u0022,\\u0022backgroundRepeat\\u0022:\\u0022no-repeat\\u0022,\\u0022backgroundSizeMode\\u0022:\\u0022cover\\u0022,\\u0022backgroundSize\\u0022:\\u0022cover\\u0022,\\u0022backgroundWidth\\u0022:\\u0022100px\\u0022,\\u0022backgroundHeight\\u0022:\\u0022100px\\u0022,\\u0022backgroundUrl\\u0022:\\u0022url()\\u0022,\\u0022backgroundColor\\u0022:\\u0022rgba( 0, 0, 0, 0 )\\u0022,\\u0022fieldBorderRadius\\u0022:\\u00223px\\u0022,\\u0022fieldBorderStyle\\u0022:\\u0022solid\\u0022,\\u0022fieldBorderSize\\u0022:\\u00221px\\u0022,\\u0022fieldBackgroundColor\\u0022:\\u0022#ffffff\\u0022,\\u0022fieldBorderColor\\u0022:\\u0022rgba( 0, 0, 0, 0.25 )\\u0022,\\u0022fieldTextColor\\u0022:\\u0022rgba( 0, 0, 0, 0.7 )\\u0022,\\u0022fieldMenuColor\\u0022:\\u0022#ffffff\\u0022,\\u0022labelSize\\u0022:\\u0022medium\\u0022,\\u0022labelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.85 )\\u0022,\\u0022labelSublabelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.55 )\\u0022,\\u0022labelErrorColor\\u0022:\\u0022#d63637\\u0022,\\u0022buttonSize\\u0022:\\u0022medium\\u0022,\\u0022buttonBorderStyle\\u0022:\\u0022none\\u0022,\\u0022buttonBorderSize\\u0022:\\u00221px\\u0022,\\u0022buttonBorderRadius\\u0022:\\u00223px\\u0022,\\u0022buttonBackgroundColor\\u0022:\\u0022#066aab\\u0022,\\u002