}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Bali</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>A tropical paradise filled with beautiful beaches, vibrant culture, and unforgettable experiences.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Bali</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"color\":{\"background\":\"#ededed\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"width\":\"1px\",\"radius\":{\"topLeft\":\"5px\",\"topRight\":\"5px\",\"bottomLeft\":\"5px\",\"bottomRight\":\"5px\"}}},\"borderColor\":\"cyan-bluish-gray\"} -->\n<div class=\"wp-block-column has-border-color has-cyan-bluish-gray-border-color has-background\" style=\"border-width:1px;border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px;background-color:#ededed;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"id\":28,\"width\":\"355px\",\"height\":\"235px\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/leonard-cotte-R5scocnOOdM-unsplash-1-scaled.jpg\" alt=\"\" class=\"wp-image-28\" style=\"object-fit:cover;width:355px;height:235px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Paris</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Experience charming streets, world-famous cuisine, and unforgettable moments.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Paris</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"color\":{\"background\":\"#ededed\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"width\":\"1px\",\"radius\":{\"topLeft\":\"5px\",\"topRight\":\"5px\",\"bottomLeft\":\"5px\",\"bottomRight\":\"5px\"}}},\"borderColor\":\"cyan-bluish-gray\"} -->\n<div class=\"wp-block-column has-border-color has-cyan-bluish-gray-border-color has-background\" style=\"border-width:1px;border-top-left-radius:5px;border-top-right-radius:5px;border-bottom-left-radius:5px;border-bottom-right-radius:5px;background-color:#ededed;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:image {\"id\":29,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/darcey-beau-q8D7WZc40eA-unsplash-1-scaled.jpg\" alt=\"\" class=\"wp-image-29\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading h