olor has-text-color has-link-color\">Have a destination in mind? We’re here to help you turn your travel dreams into unforgettable journeys.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Destinations</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->', 'Contact', '', 'inherit', 'closed', 'closed', '', '19-revision-v1', '', '', '2026-09-05 19:37:47', '2026-09-05 19:37:47', '', 19, 'http://localhost/portfolio/?p=67', 0, 'revision', '', 0),
(68, 1, '2026-09-05 20:10:59', '2026-09-05 20:10:59', '<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Travel Guides &amp; Tips</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\">Plan smarter, travel better, and make every journey unforgettable with our helpful travel guides, practical tips, and inspiring ideas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":69,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/istockphoto-1852190119-612x612-1.webp\" alt=\"\" class=\"wp-image-69\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Destination Guides</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Explore detailed guides to beautiful destinations, local attractions, culture, food, and experiences worth discovering.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":70,\"width\":\"auto\",\"height\":\"234px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/istockphoto-2223748059-612x612-1.webp\" alt=\"\" class=\"wp-image-70\" style=\"width:auto;height:234px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Travel Planning</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Get practical advice on planning your trips, choosing accommodations, creating itineraries, and making your travel experience stress-free.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":72,\"width\":\"350px\",\"height\":\"234px\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/tom-cleary-mQGW_5zcEVk-unsplash-1-1024x765.jpg\" alt=\"\" class=\"wp-image-72\" style=\"object-fit:cover;width:350px;height:234px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Travel Tips &amp; Advice</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Discover useful tips for packing, budgeting, staying safe, finding local experiences, and making the most of every journey.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Featured Travel Guides</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":73,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/istockphoto-2223748059-612x612-2.webp\" alt=\"\" class=\"wp-image-73\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How to Travel on a Budget</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Discover simple ways to save on flights, accommodation, food, and activities while still enjoying an amazing travel experience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Read Guide</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">The Ultimate Weekend Getaway</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Make the most of a short trip with simple planning ideas, destination inspiration, and tips for creating the perfect weekend escape.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/portfolio/?page_id=13\">Read Guide</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":74,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/mesut-kaya-eOcyhe5-9sQ-unsplash-1-1024x683.jpg\" alt=\"\" class=\"wp-image-74\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":75,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/mike-swigunski-k9Zeq6EH_bk-unsplash-2-1-1024x576.jpg\" alt=\"\" class=\"wp-image-75\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Essential Travel Packing Guide</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Pack smarter with practical tips on choosing what to bring, organizing your luggage, and preparing for a comfortable journey.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/portfolio/?page_id=13\">Read Guide</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:cover {\"url\":\"http://localhost/portfolio/wp-content/uploads/2026/09/premium_photo-1681488267974-2e8438b60d4f.avif\",\"id\":78,\"dimRatio\":20,\"customOverlayColor\":\"#c3d8c2\",\"isUserOverlayColor\":false,\"isDark\":false,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover is-light\"><img class=\"wp-block-cover__image-background wp-image-78 size-full\" alt=\"\" src=\"http://localhost/portfolio/wp-content/uploads/2026/09/premium_photo-1681488267974-2e8438b60d4f.avif\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-20 has-background-dim\" style=\"background-color:#c3d8c2\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|ast-global-color-8\"}}}},\"textColor\":\"ast-global-color-8\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-ast-global-color-8-color has-text-color has-link-color has-large-font-size\"><strong>Ready to Plan Your Next Adventure?</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Explore our destinations and discover the perfect place for your next unforgettable journey.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Destinations</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->', 'Travel Guides', '', 'inherit', 'closed', 'closed', '', '13-autosave-v1', '', '', '2026-09-05 20:10:59', '2026-09-05 20:10:59', '', 13, 'http://localhost/portfolio/?p=68', 0, 'revision', '', 0),
