mage size-large\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/mike-swigunski-k9Zeq6EH_bk-unsplash-2-1-1024x576.jpg\" alt=\"\" class=\"wp-image-75\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Essential Travel Packing Guide</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Pack smarter with practical tips on choosing what to bring, organizing your luggage, and preparing for a comfortable journey.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/portfolio/?page_id=13\">Read Guide</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:cover {\"url\":\"http://localhost/portfolio/wp-content/uploads/2026/09/premium_photo-1681488267974-2e8438b60d4f.avif\",\"id\":78,\"dimRatio\":20,\"customOverlayColor\":\"#c3d8c2\",\"isUserOverlayColor\":false,\"isDark\":false,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover is-light\"><img class=\"wp-block-cover__image-background wp-image-78 size-full\" alt=\"\" src=\"http://localhost/portfolio/wp-content/uploads/2026/09/premium_photo-1681488267974-2e8438b60d4f.avif\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-20 has-background-dim\" style=\"background-color:#c3d8c2\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|ast-global-color-8\"}}}},\"textColor\":\"ast-global-color-8\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-ast-global-color-8-color has-text-color has-link-color has-large-font-size\"><strong>Ready to Plan Your Next Adventure?</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Explore our destinations and discover the perfect place for your next unforgettable journey.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Explore Destinations</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->', 'Travel Guides', '', 'inherit', 'closed', 'closed', '', '13-revision-v1', '', '', '2026-09-05 20:11:08', '2026-09-05 20:11:08', '', 13, 'http://localhost/portfolio/?p=80', 0, 'revision', '', 0);
