h3 class=\"wp-block-heading has-text-align-center\">Memorable Journeys</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Create unforgettable memories with inspiring destinations and experiences you\'ll want to remember.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:cover {\"url\":\"http://localhost/portfolio/wp-content/uploads/2026/09/premium_photo-1681488267974-2e8438b60d4f.avif\",\"id\":78,\"dimRatio\":50,\"customOverlayColor\":\"#a8938f\",\"isUserOverlayColor\":true,\"isDark\":false,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover is-light\"><img class=\"wp-block-cover__image-background wp-image-78 size-full\" alt=\"\" src=\"http://localhost/portfolio/wp-content/uploads/2026/09/premium_photo-1681488267974-2e8438b60d4f.avif\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#a8938f\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"border\":{\"radius\":{\"topLeft\":\"10px\",\"topRight\":\"10px\",\"bottomLeft\":\"10px\",\"bottomRight\":\"10px\"}}},\"gradient\":\"very-light-gray-to-cyan-bluish-gray\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-very-light-gray-to-cyan-bluish-gray-gradient-background has-background has-large-font-size\" style=\"border-top-left-radius:10px;border-top-right-radius:10px;border-bottom-left-radius:10px;border-bottom-right-radius:10px\">Ready to Explore the World?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Your next unforgettable adventure is just a click away.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/portfolio/?page_id=11\">Start Exploring</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Home', '', 'inherit', 'closed', 'closed', '', '9-revision-v1', '', '', '2026-09-05 20:15:18', '2026-09-05 20:15:18', '', 9, 'http://localhost/portfolio/?p=82', 0, 'revision', '', 0),
