(86, 1, '2026-09-05 20:45:02', '2026-09-05 20:45:02', '<!-- wp:cover {\"url\":\"http://localhost/portfolio/wp-content/uploads/2026/09/pexels-freestockpro-3278215-1-scaled.jpg\",\"id\":59,\"dimRatio\":40,\"customOverlayColor\":\"#a4a8ad\",\"isUserOverlayColor\":false,\"minHeight\":450,\"isDark\":false,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover is-light\" style=\"min-height:450px\"><img class=\"wp-block-cover__image-background wp-image-59 size-full\" alt=\"\" src=\"http://localhost/portfolio/wp-content/uploads/2026/09/pexels-freestockpro-3278215-1-scaled.jpg\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-40 has-background-dim\" style=\"background-color:#a4a8ad\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|ast-global-color-4\"}}}},\"textColor\":\"ast-global-color-4\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-ast-global-color-4-color has-text-color has-link-color has-large-font-size\"><strong>Travel With Purpose. Discover With Wanderly.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|ast-global-color-4\"}}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"ast-global-color-4\"} -->\n<p class=\"has-text-align-center has-ast-global-color-4-color has-text-color has-link-color\">We believe every journey should be more than a destination — it should be a story worth remembering.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Our Story</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"10rem\",\"right\":\"10rem\"}}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\" style=\"padding-top:0;padding-right:10rem;padding-bottom:0;padding-left:10rem\">Wanderly was created for travelers who believe the best journeys begin with curiosity.                        We bring together inspiring destinations, practical travel guidance, and thoughtfully selected experiences to help you plan with confidence and explore with excitement.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\">What Makes Wanderly Different?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Curated Experiences</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\">We carefully select destinations and experiences that make every journey meaningful, exciting, and memorable.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Trusted Inspiration</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\">Get reliable travel ideas, helpful guides, and practical tips to make planning your journey easier.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Memorable Journeys</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\">Turn your travel plans into unforgettable memories with experiences you’ll want to share and remember.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":84,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/portfolio/wp-content/uploads/2026/09/photo-1539635278303-d4002c07eae3.avif\" alt=\"\" class=\"wp-image-84\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Our Travel Philosophy</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">Travel is about discovering new places, experiencing different cultures, and creating moments that stay with you. At Wanderly, we believe thoughtful planning and an open mind can turn any journey into an unforgettable adventure.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:cover {\"url\":\"http://localhost/portfolio/wp-content/uploads/2026/09/premium_photo-1664302215418-5a26e27f7b44.avif\",\"id\":85,\"dimRatio\":50,\"customOverlayColor\":\"#767271\",\"isUserOverlayColor\":false,\"minHeight\":400,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover\" style=\"min-height:400px\"><img class=\"wp-block-cover__image-background wp-image-85 size-full\" alt=\"\" src=\"http://localhost/po